def rule(ctx):
    types = ctx.types
    left = ctx.left
    rem = ctx.remaining
    n = len(ctx.robots)
    if n > 0:
        sum_c = sum(r.count for r in ctx.robots)
        sum_h = sum(r.hours for r in ctx.robots)
        mean_c = sum_c / n
        mean_h = sum_h / n
    else:
        mean_c = 0.0
        mean_h = 0.0

    min_work = 1e9
    for k in range(len(types)):
        if types[k] is not None:
            w = types[k]["work_time"]
            if w < min_work:
                min_work = w
    if min_work == 1e9:
        min_work = 1.0

    avail = list(ctx.available)
    if avail:
        scored = []
        for r in avail:
            typ = types[r.type]
            w = typ["work_time"]
            c = r.count
            h = r.hours
            d = r.duties_left
            fit = 0.0
            if w > rem + 1e-9:
                fit = 10000.0 + (w - rem)
            else:
                rem_after = rem - w
                if rem_after > 1e-9 and rem_after < min_work - 1e-9:
                    fit = 100.0 + (min_work - rem_after)
            if n > 0:
                delta_c = 2.0 * (c - mean_c)
                delta_h = 2.0 * w * (h - mean_h) + w * w * (1.0 - 1.0 / n)
            else:
                delta_c = 0.0
                delta_h = 0.0
            score = delta_c + delta_h / 100.0 + 1000.0 * fit
            if r.first_maint is None:
                score -= 0.2 * d
            scored.append((score, c, h, r.idx, r))
        scored.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        sorted_available = [x[4] for x in scored]
    else:
        sorted_available = []

    valid_types = []
    for k in range(len(types)):
        if types[k] is not None and left[k] > 0:
            typ = types[k]
            w = typ["work_time"]
            fit = 0.0
            if w > rem + 1e-9:
                fit = 10000.0 + (w - rem)
            else:
                rem_after = rem - w
                if rem_after > 1e-9 and rem_after < min_work - 1e-9:
                    fit = 100.0 + (min_work - rem_after)
            if n > 0:
                delta_c = 2.0 * (0 - mean_c) + (1.0 - 1.0 / n)
                delta_h = 2.0 * w * (0 - mean_h) + w * w * (1.0 - 1.0 / n)
            else:
                delta_c = 0.0
                delta_h = 0.0
            budget_per_duty = typ["single_work_time"]
            if budget_per_duty <= 1e-9:
                budget_per_duty = 1.0
            duties_before_maint = typ["continue_max_work"] / budget_per_duty
            score = delta_c + delta_h / 100.0 + 1000.0 * fit
            score -= 0.5 * duties_before_maint
            score += 0.1 * typ["maintenance_time"] + 0.05 * typ["charge_time"]
            valid_types.append((score, w, k))
    valid_types.sort(key=lambda x: (x[0], x[1], x[2]))
    sorted_types = [x[2] for x in valid_types]

    new_list = []
    gene = ctx.gene_type
    if gene is not None and 0 <= gene < len(types) and types[gene] is not None and left[gene] > 0:
        gene_fits = types[gene]["work_time"] <= rem + 1e-9
        any_fits = any(types[k]["work_time"] <= rem + 1e-9 for k in sorted_types)
        if gene_fits or not any_fits:
            new_list.append(gene)
    for k in sorted_types:
        if k not in new_list:
            new_list.append(k)
    if gene is not None and 0 <= gene < len(types) and types[gene] is not None and left[gene] > 0:
        if gene not in new_list:
            new_list.append(gene)

    if not sorted_available:
        if new_list:
            return [("new", k) for k in new_list]
        else:
            return [("new", ctx.gene_type)]

    if new_list and ctx.capacity < ctx.remaining:
        best_new = new_list[0]
        new_fits = types[best_new]["work_time"] <= rem + 1e-9
        avail_fits = any(types[r.type]["work_time"] <= rem + 1e-9 for r in sorted_available)
        if new_fits or not avail_fits:
            actions = [("new", k) for k in new_list]
            actions += [("reuse", r) for r in sorted_available]
            return actions

    actions = [("reuse", r) for r in sorted_available]
    actions += [("new", k) for k in new_list]
    return actions

