        if t is None:
            return 0
        return t.get("work_time", 0)

    if ctx.robots:
        min_count = min(r.count for r in ctx.robots)
    else:
        min_count = 0
    cap = min_count + 2

    def avail_key(r):
        t = ctx.types[r.type]
        wt = t.get("work_time", 0) if t is not None else 0
        over = r.count - cap
        if over < 0:
            over = 0
        return (over, r.duties_left, r.count, r.hours + wt, r.ready, r.idx)

    avail = sorted(ctx.available, key=avail_key)
    actions = [("reuse", r) for r in avail]

    def new_key(k):
        t = ctx.types[k]
        if t is None or ctx.left[k] <= 0:
            return (1, 0, 0, 0, 0, 0, 0, k)
        work = t.get("work_time", 0)
        out = t.get("out_travel_time", 0)
        ret = t.get("return_travel_time", 0)
        charge = t.get("charge_time", 0)
        maint = t.get("maintenance_time", 0)
        sw = t.get("single_work_time", 0)
        cmw = t.get("continue_max_work", 0)
        if sw > 0:
            duties = cmw / sw
        else:
            duties = 0
        busy = work + out + ret + charge
        total = duties * busy + maint
        if total > 0:
            eff = (duties * work) / total
        else:
            eff = 0
        overshoot = work - ctx.remaining
        if overshoot < 0:
            overshoot = 0
        gene_penalty = 0 if k == ctx.gene_type else 1
        return (0, -eff, overshoot, -work, maint, -ctx.left[k], gene_penalty, k)

    new_types = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]
    new_types.sort(key=new_key)
    actions.extend(("new", k) for k in new_types)
    return actions

def rule(ctx):
    av = list(ctx.available)
    av.sort(key=lambda r: (r.count, r.hours, -r.budget, r.idx))
    actions = [("reuse", r) for r in av]

    valid = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            valid.append(k)

    new_order = []
    if ctx.gene_type in valid:
        new_order.append(ctx.gene_type)
        valid.remove(ctx.gene_type)

    def score(k):
        t = ctx.types[k]
        return (
            (t['continue_max_work'] / max(t['single_work_time'], 1e-9))
            * t['work_time']
            / (t['maintenance_time'] + t['charge_time'] + 1e-9)
        )

    valid.sort(key=score, reverse=True)
    new_order.extend(valid)
    actions.extend(("new", k) for k in new_order)

    if not new_order:
        actions.append(("new", ctx.gene_type))

    return actions

