        over_abs = r.count - cap
        if over_abs < 0:
            over_abs = 0
        count_dev = r.count - avg_count
        if count_dev < 0:
            count_dev = -count_dev
        hours_dev = (r.hours + wt) - avg_hours
        if hours_dev < 0:
            hours_dev = -hours_dev
        return (over_abs, r.duties_left, count_dev, r.count, hours_dev, r.ready, r.idx)

    avail = sorted(ctx.available, key=avail_key)
    actions = [("reuse", r) for r in avail]

