        work = t.get("work_time", 0)
        out = t.get("out_travel_time", 0)
        ret = t.get("return_travel_time", 0)
        charge = t.get("charge_time", 0)
        maint = t.get("maintenance_time", 0)
        sw = t.get("single_work_time", 0)
        cmw = t.get("continue_max_work", 0)
        if sw > 0:
            duties = cmw / float(sw)
        else:
            duties = 0.0
        busy = work + out + ret + charge
        total = duties * busy + maint
        if total > 0:
            eff = (duties * work) / total
        else:
            eff = 0.0
        time_to_maint = duties * busy if busy > 0 else 0.0
        if time_to_maint >= rem:
            horizon_eff = work / float(busy) if busy > 0 else 0.0
        else:
            horizon_eff = eff
        overshoot = work - rem
        if overshoot < 0:
            overshoot = 0
        gene_penalty = 0 if k == ctx.gene_type else 1
        return (overshoot, -horizon_eff, -work if work <= rem else 0, maint, gene_penalty, -ctx.left[k], k)

    new_types = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            new_types.append(k)
    new_types.sort(key=new_key)
    actions.extend(("new", k) for k in new_types)
    return actions

def rule(ctx):
    types = ctx.types
    remaining = float(ctx.remaining)
    if remaining < 1.0:
        remaining = 1.0
    t = float(ctx.t)
    robots = ctx.robots
    n_robots = len(robots)

    def work_of(r):
        th = types[r.type]
        if th is None:
            return 10.0
        w = float(th.get("work_time", 0.0) or 0.0)
        if w <= 0.0:
            w = float(th.get("single_work_time", 0.0) or 0.0)
        if w <= 0.0:
            w = 10.0
        return w

    if n_robots:
        avg_count = sum(r.count for r in robots) / float(n_robots)
        avg_hours = sum(r.hours for r in robots) / float(n_robots)
        avg_work = sum(work_of(r) for r in robots) / float(n_robots)
    else:
        avg_count = 0.0
        avg_hours = 0.0
        avg_work = 10.0
        total_work = 0.0
        n_work = 0
        for th in types:
            if th is not None:
                w = float(th.get("work_time", 0.0) or 0.0)
                if w <= 0.0:
                    w = float(th.get("single_work_time", 0.0) or 0.0)
                if w > 0.0:
                    total_work += w
                    n_work += 1
        if n_work > 0:
            avg_work = total_work / float(n_work)

    if avg_work <= 0.0:
        avg_work = 10.0

    cap = float(ctx.capacity) if n_robots else 0.0
    cap_ratio = cap / remaining if remaining > 0.0 else 1.0
    tight = cap_ratio < 1.05

    n_types = len(types)
    type_flex = [0.0] * n_types
    for k in range(n_types):
        if types[k] is not None and k < len(ctx.left):
            type_flex[k] += float(ctx.left[k]) * 0.35
    for r in robots:
        if 0 <= r.type < n_types:
            dl = float(r.duties_left)
            if dl < 1.0:
                dl = 1.0
            type_flex[r.type] += dl * 0.20 + 0.10

    def robot_score(r):
        th = types[r.type]
        w = work_of(r)
        out = 0.0
        ret = 0.0
        charge = 0.0
        maint = 0.0
        if th is not None:
            out = float(th.get("out_travel_time", 0.0) or 0.0)
            ret = float(th.get("return_travel_time", 0.0) or 0.0)
            charge = float(th.get("charge_time", 0.0) or 0.0)
            maint = float(th.get("maintenance_time", 0.0) or 0.0)

