        if t is None or ctx.left[k] <= 0:
            return (1, 0, 0, 0, 0, 0, 0, k)
        work = t.get("work_time", 0)
        out = t.get("out_travel_time", 0)
        ret = t.get("return_travel_time", 0)
        charge = t.get("charge_time", 0)
        maint = t.get("maintenance_time", 0)
        sw = t.get("single_work_time", 0)
        cmw = t.get("continue_max_work", 0)
        if sw > 0:
            duties = cmw / float(sw)
        else:
            duties = 0.0
        busy = work + out + ret + charge
        total = duties * busy + maint
        if total > 0:
            eff = (duties * work) / total
        else:
            eff = 0.0
        time_to_maint = duties * busy if busy > 0 else 0.0
        if time_to_maint >= rem:
            horizon_eff = work / float(busy) if busy > 0 else 0.0
        else:
            horizon_eff = eff
        overshoot = work - rem
        if overshoot < 0:
            overshoot = 0
        gene_penalty = 0 if k == ctx.gene_type else 1
        return (overshoot, -horizon_eff, -work if work <= rem else 0, maint, gene_penalty, -ctx.left[k], k)

    new_types = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            new_types.append(k)
    new_types.sort(key=new_key)
    actions.extend(("new", k) for k in new_types)
    return actions

def rule(ctx):
    # 派出勤最少（并列时剩余工时多）的可用机器人；没有可用的就新开基因指定的类型
    return [("reuse", r) for r in ctx.available] + [("new", ctx.gene_type)]
